INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6439944, 955267, 39057, '<td valign="top">Cool.</td>', 'Cool.', '2011-06-10 01:07:31.000000', NULL, 1),
(6439979, 956278, 27133, '<td valign="top">Glad to see you entered this one.</td>', 'Glad to see you entered this one.', '2011-06-10 01:18:42.000000', NULL, 1),
(6440014, 955413, 39057, '<td valign="top">good work getting us into the mind of a little kid ! I see what you are doing with the shadows. This is one of the few that actually meet the challenge of scary, fun or sexy.</td>', 'good work getting us into the mind of a little kid ! I see what you are doing with the shadows. This is one of the few that actually meet the challenge of scary, fun or sexy.', '2011-06-10 01:33:08.000000', NULL, 1),
(6440016, 956323, 39057, '<td valign="top">One of the only a few that actually meet the challenge of fun, scary or sexy.</td>', 'One of the only a few that actually meet the challenge of fun, scary or sexy.', '2011-06-10 01:33:49.000000', NULL, 1),
(6440017, 956234, 39057, '<td valign="top">One of the only a few that actually meet the challenge of fun, scary or sexy.</td>', 'One of the only a few that actually meet the challenge of fun, scary or sexy.', '2011-06-10 01:34:08.000000', NULL, 1),
(6440018, 956320, 39057, '<td valign="top">Finally...one that actually is sexy, funny or scary !!!!</td>', 'Finally...one that actually is sexy, funny or scary !!!!', '2011-06-10 01:34:27.000000', NULL, 1),
(6440039, 956265, 133588, '<td valign="top">I really love the border and colours in this. I''m guessing you were going for "scary"?</td>', 'I really love the border and colours in this. I''m guessing you were going for "scary"?', '2011-06-10 01:48:42.000000', NULL, 1),
(6440046, 956268, 133588, '<td valign="top">You should try using a low ISO, and in-camera noise-reduction to make the blacks look black and less noisey. You''ll probably need to make it a longer exposure, but that might actually work quite well, especially if the people move while you''re photographing them. It would be very creepy looking.</td>', 'You should try using a low ISO, and in-camera noise-reduction to make the blacks look black and less noisey. You''ll probably need to make it a longer exposure, but that might actually work quite well, especially if the people move while you''re photographing them. It would be very creepy looking.', '2011-06-10 01:50:27.000000', NULL, 1),
(6440053, 956319, 133588, '<td valign="top">Adorable!</td>', 'Adorable!', '2011-06-10 01:56:05.000000', NULL, 1),
(6440071, 956126, 36843, '<td valign="top">Great idea</td>', 'Great idea', '2011-06-10 02:10:51.000000', NULL, 1),
(6440074, 956320, 36843, '<td valign="top">I love it , not sure if people will moan about the visible eye</td>', 'I love it , not sure if people will moan about the visible eye', '2011-06-10 02:13:05.000000', NULL, 1),
(6440075, 956052, 36843, '<td valign="top">Nice image</td>', 'Nice image', '2011-06-10 02:13:35.000000', NULL, 1),
(6440077, 956184, 36843, '<td valign="top">Lovely image, fantastic use of the light</td>', 'Lovely image, fantastic use of the light', '2011-06-10 02:15:19.000000', NULL, 1),
(6440078, 956167, 36843, '<td valign="top">Cool</td>', 'Cool', '2011-06-10 02:18:34.000000', NULL, 1),
(6440079, 955483, 36843, '<td valign="top">Wow is right</td>', 'Wow is right', '2011-06-10 02:19:53.000000', NULL, 1),
(6440085, 955954, 129267, '<td valign="top">nice silhouetting, if not a bit on the dark side. Hard to see what action is actually going on on the dock (fishing?). With a bit of color correction, this could have easily been made to look like the moon, but the warmth of the red makes this feel like a sunset, not a night scene.</td>', 'nice silhouetting, if not a bit on the dark side. Hard to see what action is actually going on on the dock (fishing?). With a bit of color correction, this could have easily been made to look like the moon, but the warmth of the red makes this feel like a sunset, not a night scene.', '2011-06-10 02:30:39.000000', NULL, 1),
(6440086, 956184, 129267, '<td valign="top">I like the vertical shot, the textures and the color cast. I''m not sure if this is a posed scene or not, which always is a good sign. To be a bit nit picky, the pose of the female seems a bit stiff, especially contrasted to the pose of the male.</td>', 'I like the vertical shot, the textures and the color cast. I''m not sure if this is a posed scene or not, which always is a good sign. To be a bit nit picky, the pose of the female seems a bit stiff, especially contrasted to the pose of the male.', '2011-06-10 02:32:52.000000', NULL, 1),
(6440087, 955267, 51379, '<td valign="top">Wow! this will do very well. I had this same idea but thought the capture would be extremely unlikely, one in a million, even with all the elk around here ( Banff National Park). I was totally blown away when I saw thisthen I wondered is it  just too good to be a capture? so I Googled it and found the sculpture in Wyoming. What a great idea and fits the Challenge exactly! Well done. 10 from me.</td>', 'Wow! this will do very well. I had this same idea but thought the capture would be extremely unlikely, one in a million, even with all the elk around here ( Banff National Park). I was totally blown away when I saw thisthen I wondered is it  just too good to be a capture? so I Googled it and found the sculpture in Wyoming. What a great idea and fits the Challenge exactly! Well done. 10 from me.', '2011-06-10 02:33:15.000000', NULL, 1),
(6440089, 955214, 129267, '<td valign="top">I like this. <br/> <br/>The most interesting part for me is the shadow and textured asphalt. I like its crop, although I can see it working well cropped tighter as well.</td>', 'I like this.  The most interesting part for me is the shadow and textured asphalt. I like its crop, although I can see it working well cropped tighter as well.', '2011-06-10 02:34:56.000000', NULL, 1),
(6440092, 955965, 114285, '<td valign="top">Awesome, one of the better ones. 9</td>', 'Awesome, one of the better ones. 9', '2011-06-10 02:35:45.000000', NULL, 1),
(6440093, 956163, 114285, '<td valign="top">Cool shot.</td>', 'Cool shot.', '2011-06-10 02:36:18.000000', NULL, 1),
(6440095, 956179, 114285, '<td valign="top">Nice lighting.</td>', 'Nice lighting.', '2011-06-10 02:37:07.000000', NULL, 1),
(6440100, 955767, 129267, '<td valign="top">I like the sharp lines of the buildings, but I don''t think the water is really adding anything to the shot. <br/> <br/>One of the things keeping this from being a stronger image is that the horizon appears to be leaning quite a bit. A simple rotation would fix that.</td>', 'I like the sharp lines of the buildings, but I don''t think the water is really adding anything to the shot.  One of the things keeping this from being a stronger image is that the horizon appears to be leaning quite a bit. A simple rotation would fix that.', '2011-06-10 02:39:34.000000', NULL, 1),
(6440104, 956049, 129267, '<td valign="top">I like the composition, very strong lines, and interesting points on all the 3rds. I also enjoy the strong horizontal nature of the shot, but I don''t think that the huge black borders or the large white stripes add to the shot.</td>', 'I like the composition, very strong lines, and interesting points on all the 3rds. I also enjoy the strong horizontal nature of the shot, but I don''t think that the huge black borders or the large white stripes add to the shot.', '2011-06-10 02:42:35.000000', NULL, 1),
(6440107, 956052, 129267, '<td valign="top">ooh, neato!<br/> <br/>very cool object, and interesting layered effect. What''s causing the slight orange tinging?</td>', 'ooh, neato! very cool object, and interesting layered effect. What''s causing the slight orange tinging?', '2011-06-10 02:43:53.000000', NULL, 1),
(6440109, 955992, 129267, '<td valign="top">great image that would be greatly improved by adding a 2nd set of feet in the doorway. <br/> <br/>never would have thought of shooting this angle, but I absolutely love the narrative it gives.</td>', 'great image that would be greatly improved by adding a 2nd set of feet in the doorway.  never would have thought of shooting this angle, but I absolutely love the narrative it gives.', '2011-06-10 02:45:15.000000', NULL, 1),
(6440110, 956126, 129267, '<td valign="top">Not a technically bad shot, but I do with that the light source wasn''t in the shot. It adds a distracting element that doesn''t improve the narrative of the scene.</td>', 'Not a technically bad shot, but I do with that the light source wasn''t in the shot. It adds a distracting element that doesn''t improve the narrative of the scene.', '2011-06-10 02:46:36.000000', NULL, 1),
(6440115, 956278, 129267, '<td valign="top">This is composed a lot better than your hundred meters entry, a little bit of breathing room is nice. I think for this shot, I would have liked to have seen the water just a bit smoother (longer exposure), as it seems to be sputtering instead of flowing.</td>', 'This is composed a lot better than your hundred meters entry, a little bit of breathing room is nice. I think for this shot, I would have liked to have seen the water just a bit smoother (longer exposure), as it seems to be sputtering instead of flowing.', '2011-06-10 02:50:38.000000', NULL, 1),
(6440118, 956320, 129267, '<td valign="top">the reflection via knife is a nice touch, but for me the window tells the story. I can''t say I terribly like the photo, but it is successful in making me feel a bit nervous.</td>', 'the reflection via knife is a nice touch, but for me the window tells the story. I can''t say I terribly like the photo, but it is successful in making me feel a bit nervous.', '2011-06-10 02:52:09.000000', NULL, 1),
(6440120, 956322, 129267, '<td valign="top">The coloration of the wine glass is nice, and the silhouette is very crisp. It''s not a terribly exciting shot, but I suspect it will do well, as it''s very technically well done.</td>', 'The coloration of the wine glass is nice, and the silhouette is very crisp. It''s not a terribly exciting shot, but I suspect it will do well, as it''s very technically well done.', '2011-06-10 02:53:51.000000', NULL, 1),
(6440122, 956234, 129267, '<td valign="top">good background, a bit cheesy of a pose. With this being advance editing, I would have liked for the couple to have been just a bit more silhouetted. Black and white was a good choice for this, it comes off as being film noir-ish.</td>', 'good background, a bit cheesy of a pose. With this being advance editing, I would have liked for the couple to have been just a bit more silhouetted. Black and white was a good choice for this, it comes off as being film noir-ish.', '2011-06-10 02:55:30.000000', NULL, 1),
(6440127, 956234, 134098, '<td valign="top">Great shot of you guys!</td>', 'Great shot of you guys!', '2011-06-10 02:59:10.000000', NULL, 1),
(6440153, 956166, 129267, '<td valign="top">I''m not sure really what the point of interest in this is supposed to be.</td>', 'I''m not sure really what the point of interest in this is supposed to be.', '2011-06-10 03:35:38.000000', NULL, 1),
(6440154, 956323, 129267, '<td valign="top">is he/she holding something in their right hand?<br/> <br/>texture is good, as is the lighting. I think the shadow being cropped is hurting you a little bit, as is not being able to tell what the person is doing. The pose is menacing, but there''s not enough information visible to see what those intentions are.</td>', 'is he/she holding something in their right hand? texture is good, as is the lighting. I think the shadow being cropped is hurting you a little bit, as is not being able to tell what the person is doing. The pose is menacing, but there''s not enough information visible to see what those intentions are.', '2011-06-10 03:38:34.000000', NULL, 1),
(6440155, 956323, 54645, '<td valign="top">Effective, I like it</td>', 'Effective, I like it', '2011-06-10 03:39:22.000000', NULL, 1),
(6440156, 956125, 129267, '<td valign="top">I don''t get a feeling of night time from this. Although I do find ants to be interesting subject matters, this one feels a bit shoehorned in there.</td>', 'I don''t get a feeling of night time from this. Although I do find ants to be interesting subject matters, this one feels a bit shoehorned in there.', '2011-06-10 03:39:59.000000', NULL, 1),
(6440157, 955784, 54645, '<td valign="top">What a powerful draw this has.</td>', 'What a powerful draw this has.', '2011-06-10 03:40:06.000000', NULL, 1),
(6440158, 956307, 129267, '<td valign="top">I find this to be a bit sad, it makes me think of the families of war casualties.</td>', 'I find this to be a bit sad, it makes me think of the families of war casualties.', '2011-06-10 03:40:55.000000', NULL, 1),
(6440159, 955992, 113156, '<td valign="top">The texture and the light on tiles is wonderful, the leg walking away superb, overall a marvelous job done.</td>', 'The texture and the light on tiles is wonderful, the leg walking away superb, overall a marvelous job done.', '2011-06-10 03:42:17.000000', NULL, 1),
(6440160, 956319, 129267, '<td valign="top">are these paper cutouts?  <br/> <br/>the grain is awesome, as is the low contrast area in the bottom. This would be made stronger for me with the background ''dudes'' a bit more OOF, and pushed more to the left plane.</td>', 'are these paper cutouts?   the grain is awesome, as is the low contrast area in the bottom. This would be made stronger for me with the background ''dudes'' a bit more OOF, and pushed more to the left plane.', '2011-06-10 03:43:01.000000', NULL, 1),
(6440162, 956288, 129267, '<td valign="top">fun shot, but doesn''t really scream out ''night-time'' to me. I love the upside down dude, but the circular thing in the background is extremely distracting -- it looks like an airplane window.</td>', 'fun shot, but doesn''t really scream out ''night-time'' to me. I love the upside down dude, but the circular thing in the background is extremely distracting -- it looks like an airplane window.', '2011-06-10 03:44:28.000000', NULL, 1),
(6440163, 956185, 113156, '<td valign="top">the forest at night, very pleasing scene and nice light.</td>', 'the forest at night, very pleasing scene and nice light.', '2011-06-10 03:44:38.000000', NULL, 1),
(6440164, 955905, 129267, '<td valign="top">Nice line, I like the cropping of the beach. I think I would have liked this one to be taken a bit later, it still feels like sunset as opposed to "night." Some parts of the water seem to be a bit over-sharpened.</td>', 'Nice line, I like the cropping of the beach. I think I would have liked this one to be taken a bit later, it still feels like sunset as opposed to "night." Some parts of the water seem to be a bit over-sharpened.', '2011-06-10 03:46:49.000000', NULL, 1),
(6440165, 955483, 129267, '<td valign="top">great shot of the sky. Wish there was a bit more context of the male standing there, -- his feet on a hill, or next to a telescope, anything.</td>', 'great shot of the sky. Wish there was a bit more context of the male standing there, -- his feet on a hill, or next to a telescope, anything.', '2011-06-10 03:47:52.000000', NULL, 1),
(6440166, 955293, 129267, '<td valign="top">This doesn''t really feel like Night time to me. <br/> <br/>As for the silhouette, it''s well done, but I wish there was more of a story to go along with the shapes. It''s a bit on the plain side, which leaves me wanting some greater narrative, or visual "wow" to go along with it.</td>', 'This doesn''t really feel like Night time to me.  As for the silhouette, it''s well done, but I wish there was more of a story to go along with the shapes. It''s a bit on the plain side, which leaves me wanting some greater narrative, or visual "wow" to go along with it.', '2011-06-10 03:50:13.000000', NULL, 1),
(6440167, 955965, 113156, '<td valign="top">The processing is fantastic, composition is spot on, and the overall ambiance superb, a truly fine photo. Gets the max from me.</td>', 'The processing is fantastic, composition is spot on, and the overall ambiance superb, a truly fine photo. Gets the max from me.', '2011-06-10 03:50:24.000000', NULL, 1),
(6440168, 956268, 113156, '<td valign="top">Well spotted.</td>', 'Well spotted.', '2011-06-10 03:53:13.000000', NULL, 1),
(6440169, 955885, 113156, '<td valign="top">Lovely photo, the silhouette is perfect and the meaning quite profound.</td>', 'Lovely photo, the silhouette is perfect and the meaning quite profound.', '2011-06-10 03:54:59.000000', NULL, 1),
(6440174, 955267, 129267, '<td valign="top">interesting shot, well framed, and believable night scene despite the coloration. Wish the frontmost doe wasn''t there, would have made this so surreal.</td>', 'interesting shot, well framed, and believable night scene despite the coloration. Wish the frontmost doe wasn''t there, would have made this so surreal.', '2011-06-10 04:06:07.000000', NULL, 1),
(6440176, 956321, 129267, '<td valign="top">What a strange pose, with the hat on, she reminds me of a mime. The park bench adds character and story, but th background plants and brick wall take away some of the impact.</td>', 'What a strange pose, with the hat on, she reminds me of a mime. The park bench adds character and story, but th background plants and brick wall take away some of the impact.', '2011-06-10 04:07:28.000000', NULL, 1),
(6440177, 956316, 129267, '<td valign="top">great shot, know this feeling well. A little more breathing room on the bottom would bump this up an extra point for me.</td>', 'great shot, know this feeling well. A little more breathing room on the bottom would bump this up an extra point for me.', '2011-06-10 04:08:40.000000', NULL, 1),
(6440178, 955267, 106484, '<td valign="top">Great shot! Although it looks like a day time shot which has been post processed. Still....it gets a high score from me.</td>', 'Great shot! Although it looks like a day time shot which has been post processed. Still....it gets a high score from me.', '2011-06-10 04:10:45.000000', NULL, 1),
(6440179, 956163, 129267, '<td valign="top">very cool effect, reminds me of those circus acts where a performer is strapped on a wheel and various sharp objects are thrown at him -- especially with the upside-down reflection. <br/> <br/>some more consideration with the cropping would push this up an extra couple points.</td>', 'very cool effect, reminds me of those circus acts where a performer is strapped on a wheel and various sharp objects are thrown at him -- especially with the upside-down reflection.  some more consideration with the cropping would push this up an extra couple points.', '2011-06-10 04:11:19.000000', NULL, 1),
(6440180, 955784, 106484, '<td valign="top">I do like this for some strange reason.</td>', 'I do like this for some strange reason.', '2011-06-10 04:11:27.000000', NULL, 1),
(6440183, 955171, 129267, '<td valign="top">interesting photo. I can see nothing wrong with it, it all seems very considered.</td>', 'interesting photo. I can see nothing wrong with it, it all seems very considered.', '2011-06-10 04:13:26.000000', NULL, 1),
(6440184, 956185, 129267, '<td valign="top">truly does look like a fairy-tale land. Would have liked a bit more depth, everything feels very flattened around that main tree.</td>', 'truly does look like a fairy-tale land. Would have liked a bit more depth, everything feels very flattened around that main tree.', '2011-06-10 04:14:39.000000', NULL, 1),
(6440186, 956198, 106484, '<td valign="top">Great atmosphere, although the cropped chair and place mat on the left are distracting. Might have been better as a square crop.</td>', 'Great atmosphere, although the cropped chair and place mat on the left are distracting. Might have been better as a square crop.', '2011-06-10 04:15:45.000000', NULL, 1),
(6440188, 956268, 129267, '<td valign="top">interesting shot, although it makes me feel like a voyeur. <br/> <br/>would be made more interesting with some better quality, there''s a lot of haloing and noise artifacts from the crop.</td>', 'interesting shot, although it makes me feel like a voyeur.  would be made more interesting with some better quality, there''s a lot of haloing and noise artifacts from the crop.', '2011-06-10 04:16:20.000000', NULL, 1),
(6440190, 955965, 129267, '<td valign="top">Interesting sky, and gate. the angle gives me a bit of vertigo. I like the expressions of the male and female, but I can''t quite make out what the shape between them is. It looks almost like a child sitting down?</td>', 'Interesting sky, and gate. the angle gives me a bit of vertigo. I like the expressions of the male and female, but I can''t quite make out what the shape between them is. It looks almost like a child sitting down?', '2011-06-10 04:18:29.000000', NULL, 1),
(6440192, 956317, 129267, '<td valign="top">interesting photograph, I like the light sources. I wish the subject and the wispy string-like thing was just a bit more sharp.</td>', 'interesting photograph, I like the light sources. I wish the subject and the wispy string-like thing was just a bit more sharp.', '2011-06-10 04:19:41.000000', NULL, 1),
(6440195, 956195, 106484, '<td valign="top">Nice, might have worked better with the top and bottom cropped a little more, and that sky is crying out for some more post processing colour. Still, good though.</td>', 'Nice, might have worked better with the top and bottom cropped a little more, and that sky is crying out for some more post processing colour. Still, good though.', '2011-06-10 04:20:19.000000', NULL, 1),
(6440196, 956318, 129267, '<td valign="top">without the title, I would have had no clue what I was looking at. silhouette is good, but I don''t quite get the relationship between the pose and the fountain.</td>', 'without the title, I would have had no clue what I was looking at. silhouette is good, but I don''t quite get the relationship between the pose and the fountain.', '2011-06-10 04:21:00.000000', NULL, 1),
(6440198, 956266, 129267, '<td valign="top">Not a bad shot, but that border is really, really distracting. There''s some haloing around the moon, almost like a motion blur, which makes me question whether this was handshot or not.</td>', 'Not a bad shot, but that border is really, really distracting. There''s some haloing around the moon, almost like a motion blur, which makes me question whether this was handshot or not.', '2011-06-10 04:22:37.000000', NULL, 1),
(6440200, 956261, 129267, '<td valign="top">this one seems a bit stretched for me: the color makes me think of the sunset - not night time, which wouldn''t be a big deal except that this image seems to be almost entirely about the color of the sun reflected in the tide. I think a tighter crop on the bird in flight would be more successful, and still tell the same story.</td>', 'this one seems a bit stretched for me: the color makes me think of the sunset - not night time, which wouldn''t be a big deal except that this image seems to be almost entirely about the color of the sun reflected in the tide. I think a tighter crop on the bird in flight would be more successful, and still tell the same story.', '2011-06-10 04:27:35.000000', NULL, 1),
(6440201, 956167, 129267, '<td valign="top">hey... your sniper is missing his/her scope!<br/> <br/>good location, good exposure, guessing HDR as I can see a bit of haloing around anything dark. The bird in flight adds to this image. I think I''d like to see the hard edge of the head instead of a hood.</td>', 'hey... your sniper is missing his/her scope! good location, good exposure, guessing HDR as I can see a bit of haloing around anything dark. The bird in flight adds to this image. I think I''d like to see the hard edge of the head instead of a hood.', '2011-06-10 04:29:40.000000', NULL, 1),
(6440203, 956302, 129267, '<td valign="top">a bit on the dark side. having a hard time finding an interesting story in this. The whiskers in the bokeh are interesting, I wonder if that''s where your "true" photograph lies.</td>', 'a bit on the dark side. having a hard time finding an interesting story in this. The whiskers in the bokeh are interesting, I wonder if that''s where your "true" photograph lies.', '2011-06-10 04:32:13.000000', NULL, 1),
(6440204, 956273, 129267, '<td valign="top">quite a busy scene, with a bit too much front-lighting on the silhouette portion of the image. The most interesting thing to me is the texture you captured on the left side.</td>', 'quite a busy scene, with a bit too much front-lighting on the silhouette portion of the image. The most interesting thing to me is the texture you captured on the left side.', '2011-06-10 04:33:48.000000', NULL, 1),
(6440206, 955885, 129267, '<td valign="top">I can see this with many other different and stronger titles. <br/> <br/>The colors and composition are all nice and strong, as is the silhouette. I wish we could see her feet or surroundings a bit more.</td>', 'I can see this with many other different and stronger titles.  The colors and composition are all nice and strong, as is the silhouette. I wish we could see her feet or surroundings a bit more.', '2011-06-10 04:36:03.000000', NULL, 1),
(6440208, 956198, 129267, '<td valign="top">excellent story, and relatively good tones for a single light source. I love the less-than-perfect hair, and the sweater/shirt with a collar. Her hands seem to be in an uncomfortable position, I rarely see solitaire played with two hands. <br/> <br/>on the post side, I can see quite a bit of dodging around the silhouette, it''s most noticeable at her hands and elbow region.</td>', 'excellent story, and relatively good tones for a single light source. I love the less-than-perfect hair, and the sweater/shirt with a collar. Her hands seem to be in an uncomfortable position, I rarely see solitaire played with two hands.  on the post side, I can see quite a bit of dodging around the silhouette, it''s most noticeable at her hands and elbow region.', '2011-06-10 04:39:25.000000', NULL, 1),
(6440210, 955784, 129267, '<td valign="top">I''m not finding this terribly interesting, even as an abstract. It looks/feels to me like a shadow on a curtain.</td>', 'I''m not finding this terribly interesting, even as an abstract. It looks/feels to me like a shadow on a curtain.', '2011-06-10 04:40:40.000000', NULL, 1),
(6440211, 955413, 129267, '<td valign="top">this feels more like a shadow than a silhouette. there are some really weird things going on in the foreground as well.</td>', 'this feels more like a shadow than a silhouette. there are some really weird things going on in the foreground as well.', '2011-06-10 04:42:00.000000', NULL, 1),
(6440213, 956295, 129267, '<td valign="top">I really like this image. I love her hair, and seeing the blown out sky through it. She has such a somber expression. <br/> <br/>.. but with that said, with the sky being that bright, I''m not convinced that this silhouette was taken anywhere close to night time.</td>', 'I really like this image. I love her hair, and seeing the blown out sky through it. She has such a somber expression.  .. but with that said, with the sky being that bright, I''m not convinced that this silhouette was taken anywhere close to night time.', '2011-06-10 04:44:41.000000', NULL, 1),
(6440214, 956136, 129267, '<td valign="top">colors are interesting, and I don''t mind the motion blur, but I don''t see the silhouette in this, only a side-lit portrait.</td>', 'colors are interesting, and I don''t mind the motion blur, but I don''t see the silhouette in this, only a side-lit portrait.', '2011-06-10 04:46:22.000000', NULL, 1),
(6440217, 956179, 129267, '<td valign="top">the shadows being casted by the multiple light sources are interesting but I can''t say I''m terribly fond of the photo itself. From a purely visual standpoint, It''s just not something that I''m drawn to.</td>', 'the shadows being casted by the multiple light sources are interesting but I can''t say I''m terribly fond of the photo itself. From a purely visual standpoint, It''s just not something that I''m drawn to.', '2011-06-10 04:49:05.000000', NULL, 1),
