(6442992, 956272, 107190, '<td valign="top">Hmmmm, this sort of looks like an unraveling cigar.... interesting but not a complete silhouette...</td>', 'Hmmmm, this sort of looks like an unraveling cigar.... interesting but not a complete silhouette...', '2011-06-13 13:59:45.000000', NULL, 1),
(6443016, 956163, 107190, '<td valign="top">Just the bottom half might have worked better...</td>', 'Just the bottom half might have worked better...', '2011-06-13 14:10:13.000000', NULL, 1),
(6443034, 955396, 107190, '<td valign="top">Lovely pic, just doesn''t appear to be at night...</td>', 'Lovely pic, just doesn''t appear to be at night...', '2011-06-13 14:16:20.000000', NULL, 1),
(6443207, 956163, 59796, '<td valign="top">The idea is awesome! Might''ve been even better without the reflection - it just looks a little crammed in...</td>', 'The idea is awesome! Might''ve been even better without the reflection - it just looks a little crammed in...', '2011-06-13 18:33:12.000000', NULL, 1),
(6443317, 955483, 124982, '<td valign="top">I''m very curious to know how you did such a long exposure without you moving and creating a motion blur!</td>', 'I''m very curious to know how you did such a long exposure without you moving and creating a motion blur!', '2011-06-13 22:22:50.000000', NULL, 1),
(6443320, 956185, 124982, '<td valign="top">Very dreamy indeed!! Is this a infrared image? Quite gorgeous!</td>', 'Very dreamy indeed!! Is this a infrared image? Quite gorgeous!', '2011-06-13 22:24:07.000000', NULL, 1),
(6443324, 955987, 124982, '<td valign="top">This really is a beautiful capture! Normally, I dont see folks doing painting with light well...but this is a good example of where it actually adds to the image, rather than just being something cool to do. Well done!</td>', 'This really is a beautiful capture! Normally, I dont see folks doing painting with light well...but this is a good example of where it actually adds to the image, rather than just being something cool to do. Well done!', '2011-06-13 22:25:40.000000', NULL, 1),
(6443326, 956323, 124982, '<td valign="top">Excellent. This really does convey a sense of foreboding and danger! So far, this is my favourite of the challenge. Great shot!!</td>', 'Excellent. This really does convey a sense of foreboding and danger! So far, this is my favourite of the challenge. Great shot!!', '2011-06-13 22:26:59.000000', NULL, 1),
(6443327, 955905, 124982, '<td valign="top">Love the tones -- the purples and the yellows are just wonderful!</td>', 'Love the tones -- the purples and the yellows are just wonderful!', '2011-06-13 22:27:57.000000', NULL, 1),
(6443333, 956234, 124982, '<td valign="top">I''m considering giving you a 1 just because you''re A FOOT AWAY FROM HER!!! Get in there man! ;)</td>', 'I''m considering giving you a 1 just because you''re A FOOT AWAY FROM HER!!! Get in there man! ;)', '2011-06-13 22:29:19.000000', NULL, 1),
(6443443, 956185, 114285, '<td valign="top">Lovely.</td>', 'Lovely.', '2011-06-14 02:04:44.000000', NULL, 1),
(6443444, 955396, 114285, '<td valign="top">Ummm, well,,,,I guess you''ve already been told - yup no need to tell you. Shame great pic anyway.</td>', 'Ummm, well,,,,I guess you''ve already been told - yup no need to tell you. Shame great pic anyway.', '2011-06-14 02:05:46.000000', NULL, 1),
